// Hand-authored, not generated by mdatagen, so it survives regeneration. It
// specifically exercises recordDataPoint's merge path (calling it twice with
// identical attributes+timestamp), which the generated tests don't cover —
// those only ever use distinct attribute values across calls.
package metadata

import (
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
	"go.opentelemetry.io/collector/pdata/pcommon"
	"go.opentelemetry.io/collector/pdata/pmetric"
)

func newReaggregateMetric(t *testing.T, strategy string) metricReaggregateMetric {
	t.Helper()
	cfg := ReaggregateMetricMetricConfig{
		Enabled:             true,
		AggregationStrategy: strategy,
		EnabledAttributes: []ReaggregateMetricMetricAttributeKey{
			ReaggregateMetricMetricAttributeKeyStringAttr,
			ReaggregateMetricMetricAttributeKeyBooleanAttr,
		},
	}
	return newMetricReaggregateMetric(cfg)
}

func TestRecordDataPoint_MergesOnIdenticalKey_Sum(t *testing.T) {
	m := newReaggregateMetric(t, AggregationStrategySum)
	ts := pcommon.Timestamp(1000)

	m.recordDataPoint(ts, ts, 5, "db1", true)
	m.recordDataPoint(ts, ts, 7, "db1", true) // identical key -> should merge, not append

	dps := m.data.Gauge().DataPoints()
	require.Equal(t, 1, dps.Len(), "identical attributes+timestamp must merge into one data point")
	assert.InDelta(t, 12, dps.At(0).DoubleValue(), 0.0001)
}

func TestRecordDataPoint_MergesOnIdenticalKey_Avg(t *testing.T) {
	m := newReaggregateMetric(t, AggregationStrategyAvg)
	ts := pcommon.Timestamp(1000)

	m.recordDataPoint(ts, ts, 4, "db1", true)
	m.recordDataPoint(ts, ts, 10, "db1", true)

	metrics := pmetric.NewMetricSlice()
	m.emit(metrics)
	dps := metrics.At(0).Gauge().DataPoints()
	require.Equal(t, 1, dps.Len())
	assert.InDelta(t, 7, dps.At(0).DoubleValue(), 0.0001) // (4+10)/2
}

func TestRecordDataPoint_MergesOnIdenticalKey_MinMax(t *testing.T) {
	minM := newReaggregateMetric(t, AggregationStrategyMin)
	ts := pcommon.Timestamp(1000)
	minM.recordDataPoint(ts, ts, 9, "db1", true)
	minM.recordDataPoint(ts, ts, 3, "db1", true)
	minDps := minM.data.Gauge().DataPoints()
	require.Equal(t, 1, minDps.Len())
	assert.InDelta(t, 3, minDps.At(0).DoubleValue(), 0.0001)

	maxM := newReaggregateMetric(t, AggregationStrategyMax)
	maxM.recordDataPoint(ts, ts, 3, "db1", true)
	maxM.recordDataPoint(ts, ts, 9, "db1", true)
	maxDps := maxM.data.Gauge().DataPoints()
	require.Equal(t, 1, maxDps.Len())
	assert.InDelta(t, 9, maxDps.At(0).DoubleValue(), 0.0001)
}

func TestRecordDataPoint_DistinctAttributesDoNotMerge(t *testing.T) {
	m := newReaggregateMetric(t, AggregationStrategySum)
	ts := pcommon.Timestamp(1000)

	m.recordDataPoint(ts, ts, 1, "db1", true)
	m.recordDataPoint(ts, ts, 1, "db2", true)  // different string attr -> distinct series
	m.recordDataPoint(ts, ts, 1, "db1", false) // different bool attr -> distinct series

	dps := m.data.Gauge().DataPoints()
	assert.Equal(t, 3, dps.Len())
}

func TestRecordDataPoint_DistinctTimestampsDoNotMerge(t *testing.T) {
	m := newReaggregateMetric(t, AggregationStrategySum)

	m.recordDataPoint(pcommon.Timestamp(1000), pcommon.Timestamp(2000), 1, "db1", true)
	m.recordDataPoint(pcommon.Timestamp(1000), pcommon.Timestamp(3000), 1, "db1", true) // different end ts

	dps := m.data.Gauge().DataPoints()
	assert.Equal(t, 2, dps.Len())
}

// benchRecordN records n distinct data points into a fresh metric, simulating
// n distinct attribute combinations landing on one shared resource.
func benchRecordN(b *testing.B, n int) {
	b.ReportAllocs()
	for i := 0; i < b.N; i++ {
		cfg := ReaggregateMetricMetricConfig{
			Enabled:             true,
			AggregationStrategy: AggregationStrategySum,
			EnabledAttributes: []ReaggregateMetricMetricAttributeKey{
				ReaggregateMetricMetricAttributeKeyStringAttr,
				ReaggregateMetricMetricAttributeKeyBooleanAttr,
			},
		}
		m := newMetricReaggregateMetric(cfg)
		ts := pcommon.Timestamp(1000)
		for j := 0; j < n; j++ {
			m.recordDataPoint(ts, ts, float64(j), attrName(j), j%2 == 0)
		}
	}
}

func attrName(i int) string {
	const letters = "abcdefghijklmnopqrstuvwxyz"
	b := make([]byte, 0, 12)
	b = append(b, "attr_"...)
	for {
		b = append(b, letters[i%26])
		i /= 26
		if i == 0 {
			break
		}
	}
	return string(b)
}

func BenchmarkRecordDataPoint_N1(b *testing.B)    { benchRecordN(b, 1) }
func BenchmarkRecordDataPoint_N2(b *testing.B)    { benchRecordN(b, 2) }
func BenchmarkRecordDataPoint_N10(b *testing.B)   { benchRecordN(b, 10) }
func BenchmarkRecordDataPoint_N1000(b *testing.B) { benchRecordN(b, 1000) }
